WITH ranked AS (SELECT * FROM products QUALIFY ROW_NUMBER() OVER (PARTITION BY brand ORDER BY price, id) = 1) SELECT DATE_TRUNC('MONTH', launch_date) AS activity_month, COUNT(*) FILTER (WHERE category = 'Books') AS books_rows, APPROX_PERCENTILE(cost, ARRAY(0.25, 0.5, 0.75)) AS cost_quartiles, MAX(cost) AS max_cost, CORR(stock_qty, price) AS corr_stock_qty_price, BIT_AND(stock_qty) AS stock_qty_bit_and FROM ranked GROUP BY DATE_TRUNC('MONTH', launch_date) ORDER BY activity_month DESC;
